import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_matmul_cuda = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define TILE 16

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    const int M,
    const int N,
    const int K) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int row = blockIdx.y * TILE + ty;
    const int col = blockIdx.x * TILE + tx;

    float acc = 0.0f;

    for (int k0 = 0; k0 < K; k0 += TILE) {
        const int a_col = k0 + tx;
        const int b_row = k0 + ty;

        As[ty][tx] = (row < M && a_col < K)
            ? A[static_cast<long long>(row) * K + a_col]
            : 0.0f;

        Bs[ty][tx] = (b_row < K && col < N)
            ? B[static_cast<long long>(b_row) * N + col]
            : 0.0f;

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < TILE; ++kk) {
            acc += As[ty][kk] * Bs[kk][tx];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[static_cast<long long>(row) * N + col] = acc;
    }
}

torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.scalar_type() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");

    auto Ac = A.contiguous();
    auto Bc = B.contiguous();

    const int M = static_cast<int>(Ac.size(0));
    const int K = static_cast<int>(Ac.size(1));
    const int N = static_cast<int>(Bc.size(1));

    auto C = torch::empty({M, N}, Ac.options());

    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (M + TILE - 1) / TILE);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    matmul_kernel<<<grid, block, 0, stream>>>(
        Ac.data_ptr<float>(),
        Bc.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K);

    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed: ", cudaGetErrorString(err));

    return C;
}
"""

_matmul_cpp = r"""
torch::Tensor matmul(torch::Tensor A, torch::Tensor B);
"""

_ext = load_inline(
    name="modelnew_matmul_ext",
    cpp_sources=[_matmul_cpp],
    cuda_sources=[_matmul_cuda],
    functions=["matmul"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        return _ext.matmul(A, B)

